package web

import (
	"embed"
	"encoding/json"
	"fmt"
	"html/template"
	"io/fs"
	"net/http"
	"net/url"
	"strconv"
	"strings"
	"time"

	"github.com/burpsy-go/burpsy/internal/core"
)

// The /ui2/ console: server-rendered HTML with a vendored htmx client (ui2/htmx.min.js,
// ui2/sse.min.js). The React SPA at / stays the default; this slice exists to prove the
// server-driven shape against the same JSON model — one page per view, fragments swapped
// by htmx, no build step, no framework runtime in the browser.
//
//go:embed ui2
var ui2FS embed.FS

// ui2TemplateFiles lists every template: ui2/*.html plus one level of per-domain directories.
// Template names are file basenames, so basenames must be unique across domains.
func ui2TemplateFiles() []string {
	var out []string
	for _, pat := range []string{"ui2/*.html", "ui2/*/*.html"} {
		m, err := fs.Glob(ui2FS, pat)
		if err != nil {
			panic(err)
		}
		out = append(out, m...)
	}
	return out
}

// ui2Templates is every server-rendered fragment, parsed once at package init. text/template
// would work too; html/template is chosen because message bytes are attacker-controlled and
// land in these pages — auto-escaping is not optional here.
var ui2Templates = template.Must(template.New("ui2").Funcs(template.FuncMap{
	"lower": strings.ToLower,
	// urlquery percent-encodes a site-map node key for a non-URL attribute (hx-post),
	// where html/template applies no contextual URL escaping and a raw NUL in the
	// attribute value would reach the browser and be replaced with U+FFFD.
	"urlquery": url.QueryEscape,
	"until":    func(n int) []int { return make([]int, n) },
	// ms renders an epoch-millis JSON number (decoded as float64) as a wall-clock time;
	// unknown shapes render empty rather than a bogus zero date.
	"ms": func(v any) string {
		f, ok := v.(float64)
		if !ok {
			return ""
		}
		return time.UnixMilli(int64(f)).Format("2006-01-02 15:04:05")
	},
}).ParseFS(ui2FS, ui2TemplateFiles()...))

// ui2Error is the model for error.html.
type ui2Error struct{ Message string }

// ui2StatusString2 renders a *int status the way rows do ("—" when nil).
func ui2StatusString2(s *int) string {
	if s == nil {
		return "—"
	}
	return strconv.Itoa(*s)
}

// ui2Page is the per-request model for the layout wrapper.
type ui2Page struct {
	Title string
	View  string // "history" | "issues"
	Body  template.HTML
}

// ui2HistoryParams is the query state the history view round-trips through the URL, so a
// filtered/paged view is bookmarkable and htmx swaps carry the same state.
type ui2HistoryParams struct {
	Q      string // burpsy-query filter (same DSL as /api/history?q=)
	Search string // substring search over method/host/path/status
	Offset int    // server-side page offset, newest first
	Limit  int    // page size (default 100)
}

const ui2DefaultPageSize = 100
const ui2MaxPageSize = 500

func parseUI2HistoryParams(r *http.Request) ui2HistoryParams {
	q := r.URL.Query()
	p := ui2HistoryParams{
		Q:      strings.TrimSpace(q.Get("q")),
		Search: strings.TrimSpace(q.Get("search")),
		Limit:  ui2DefaultPageSize,
	}
	if n, err := strconv.Atoi(q.Get("offset")); err == nil && n > 0 {
		p.Offset = n
	}
	if n, err := strconv.Atoi(q.Get("limit")); err == nil && n > 0 {
		if n > ui2MaxPageSize {
			n = ui2MaxPageSize
		}
		p.Limit = n
	}
	return p
}

// ui2Row is one history row as the template sees it. Kept separate from ExchangeView so the
// template never needs to know the wire shape, and so the fields rendered are exactly the
// fields computed — no payloads.
type ui2Row struct {
	ID          uint64
	Method      string
	Host        string
	Port        uint16
	Path        string
	Status      string // "—" when no response yet
	Mime        string
	ResponseLen string
	DurationMs  uint64
	StartedMs   uint64
	Highlight   string
	Selected    bool
}

func ui2StatusString(s *uint16) string {
	if s == nil {
		return "—"
	}
	return strconv.Itoa(int(*s))
}

// ui2HistoryRows is the fragment model for the rows swap target.
type ui2HistoryRows struct {
	Rows       []ui2Row
	Total      int
	Matched    int
	Offset     int
	Limit      int
	NextOffset int // -1 when this page reached the end
	Q          string
	Search     string
	HasMore    bool
	// HxVals is the sentinel row's hx-vals attribute, precomputed as JSON: quoting the filter
	// and search strings inline broke the attribute's JSON (and dropped the filter from the
	// next page) whenever they contained a double quote.
	HxVals string
}

// handleUI2 is the /ui2/ subtree root: the shell page with the history view embedded.
func (s *Server) handleUI2(w http.ResponseWriter, r *http.Request) {
	page := ui2Page{Title: "burpsy /ui2/ — History", View: "history"}
	page.Body = s.renderUI2HistoryRows(r, ui2HistoryParams{Limit: ui2DefaultPageSize})
	if err := ui2Templates.ExecuteTemplate(w, "layout.html", page); err != nil {
		http.Error(w, "template error", http.StatusInternalServerError)
		return
	}
}

// handleUI2History serves GET /ui2/history: the full shell on a plain navigation, or just the
// rows fragment when htmx asks (HX-Request). The shell embeds the first page so a cold load
// needs one request.
func (s *Server) handleUI2History(w http.ResponseWriter, r *http.Request) {
	p := parseUI2HistoryParams(r)
	appendMode := r.Header.Get("HX-Request") == "true" && r.URL.Query().Get("offset") != ""
	body := s.renderUI2HistoryRows(r, p)
	if appendMode {
		// Infinite-scroll append: emit only the <tr> rows (plus the next sentinel), so the
		// htmx beforeend swap grows the tbody without replacing the block the user scrolls.
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		_, _ = w.Write([]byte(s.renderUI2HistoryRowsAppend(r, p)))
		return
	}
	if r.Header.Get("HX-Request") == "true" {
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		if _, err := w.Write([]byte(body)); err != nil {
			return
		}
		return
	}
	page := ui2Page{Title: "burpsy /ui2/ — History", View: "history", Body: body}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	if err := ui2Templates.ExecuteTemplate(w, "layout.html", page); err != nil {
		http.Error(w, "template error", http.StatusInternalServerError)
	}
}

// renderUI2HistoryRows computes one page of history rows and renders the rows fragment.
// Server-side paging: the store hands index rows only (no bodies), the filter applies before
// the page slice, so cost is O(total rows) for the scan and O(page) for the render — the
// property that keeps a 200k-row capture responsive.
func (s *Server) renderUI2HistoryRows(r *http.Request, p ui2HistoryParams) template.HTML {
	var sb strings.Builder
	_ = ui2Templates.ExecuteTemplate(&sb, "history_rows.html", s.ui2HistoryPage(r, p))
	return template.HTML(sb.String()) //nolint:gosec // html/template auto-escapes every field
}

// ui2HistoryPage computes one page of history rows into the fragment model. Server-side
// paging: the store hands index rows only (no bodies), the filter applies before the page
// slice, so cost is O(total rows) for the scan and O(page) for the render — the property
// that keeps a 200k-row capture responsive. Shared by the full fragment and the
// infinite-scroll append so the two cannot disagree about which rows a page holds.
func (s *Server) ui2HistoryPage(r *http.Request, p ui2HistoryParams) ui2HistoryRows {
	exchanges := s.store.Exchanges()

	var filter *queryFilter
	if p.Q != "" {
		f, err := compileQuery(p.Q, s.store)
		if err != nil {
			// The DSL error is rendered by the JSON API with caret art; here a plain
			// message in the rows fragment is what the operator sees inline.
			return ui2HistoryRows{
				Rows: nil, Total: len(exchanges), Matched: 0, Offset: 0, Limit: p.Limit,
				NextOffset: -1, Q: p.Q, Search: p.Search, HasMore: false,
				HxVals: ui2HistoryHxVals(-1, p),
			}
		}
		filter = f
	}

	needle := strings.ToLower(p.Search)
	matched := make([]*core.Exchange, 0, len(exchanges))
	for i := len(exchanges) - 1; i >= 0; i-- {
		ex := exchanges[i]
		switch ex.Source {
		case core.SourceRepeater, core.SourceIntruder, core.SourceScanner:
			continue
		}
		if filter != nil && !filter.match(ex) {
			continue
		}
		if needle != "" {
			hay := strings.ToLower(ex.Method + " " + ex.Host + ex.Path + " " + ui2StatusString(ex.Status))
			if !strings.Contains(hay, needle) {
				continue
			}
		}
		matched = append(matched, ex)
	}

	total := len(matched)
	end := p.Offset + p.Limit
	if end > total {
		end = total
	}
	next := -1
	if end < total {
		next = end
	}
	rows := make([]ui2Row, 0, max(end-p.Offset, 0))
	if p.Offset < total {
		for _, ex := range matched[p.Offset:end] {
			v := exchangeView(ex)
			rows = append(rows, ui2Row{
				ID:          uint64(v.ID),
				Method:      v.Method,
				Host:        v.Host,
				Port:        v.Port,
				Path:        v.Path,
				Status:      ui2StatusString(v.Status),
				Mime:        v.Mime,
				ResponseLen: strconv.Itoa(v.ResponseLen),
				DurationMs:  v.DurationMs,
				StartedMs:   v.StartedMs,
				Highlight:   v.Highlight,
			})
		}
	}
	return ui2HistoryRows{
		Rows: rows, Total: len(exchanges), Matched: total, Offset: p.Offset, Limit: p.Limit,
		NextOffset: next, Q: p.Q, Search: p.Search, HasMore: next >= 0,
		HxVals: ui2HistoryHxVals(next, p),
	}
}

// ui2HistoryHxVals is the sentinel row's hx-vals payload: JSON with the filter and search
// strings properly encoded, so any operator text round-trips into the next page request.
func ui2HistoryHxVals(next int, p ui2HistoryParams) string {
	b, _ := json.Marshal(map[string]any{"offset": next, "limit": p.Limit, "q": p.Q, "search": p.Search})
	return string(b)
}

// renderUI2HistoryRowsAppend renders just the <tr> elements for one page plus the next
// sentinel row, for the infinite-scroll beforeend swap. It shares the page computation with
// the full fragment so the two cannot disagree about which rows a page holds.
func (s *Server) renderUI2HistoryRowsAppend(r *http.Request, p ui2HistoryParams) template.HTML {
	var sb strings.Builder
	_ = ui2Templates.ExecuteTemplate(&sb, "history_rows_append.html", s.ui2HistoryPage(r, p))
	return template.HTML(sb.String()) //nolint:gosec // html/template auto-escapes every field
}

// handleUI2HistoryDetail serves GET /ui2/history/{id}: the request/response panes for one
// exchange. Message bytes are read here, one message at a time, never in the list.
func (s *Server) handleUI2HistoryDetail(w http.ResponseWriter, r *http.Request) {
	id, err := strconv.ParseUint(r.PathValue("id"), 10, 64)
	if err != nil {
		http.Error(w, "Invalid exchange ID", http.StatusBadRequest)
		return
	}
	ex, err := s.store.GetExchange(core.ExchangeID(id))
	if err != nil {
		http.Error(w, "Exchange not found", http.StatusNotFound)
		return
	}
	v := exchangeView(ex)
	model := ui2Detail{
		ID: uint64(v.ID), Method: v.Method, Host: v.Host, Port: v.Port, Path: v.Path,
		Status: ui2StatusString(v.Status), Mime: v.Mime, ResponseLen: v.ResponseLen,
		DurationMs: v.DurationMs,
	}
	if v.Request != nil {
		if msg, err := s.store.Get(core.MsgId(*v.Request)); err == nil {
			model.Request = string(msg.Raw())
		}
	}
	if model.Request == "" {
		// Restored-project case: the exchanges table carries request_msg, but the
		// in-memory Request pointer is nil after this tree's restore path, so the row
		// reads as request-less even though the bytes are on disk. Resolve through the
		// store's request index rather than guessing an id.
		if raw := requestMessageForExchange(s.store, ex); raw != nil {
			model.Request = string(raw)
		}
	}
	if v.Response != nil {
		if msg, err := s.store.Get(core.MsgId(*v.Response)); err == nil {
			model.Response = string(msg.Raw())
		}
	}
	// Pretty/Raw reading toggle, per pane. Pretty is the default reading; Raw is the exact
	// recorded bytes. The toggle only changes THIS rendering — the store is never written
	// and the bytes the repeater would re-send are untouched.
	model.ReqPretty = r.URL.Query().Get("view_req") != "raw"
	model.RespPretty = r.URL.Query().Get("view_resp") != "raw"
	model.ReqPane = renderMessagePane(model.Request, true, model.ReqPretty)
	model.RespPane = renderMessagePane(model.Response, false, model.RespPretty)
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	if err := ui2Templates.ExecuteTemplate(w, "history_detail.html", model); err != nil {
		http.Error(w, "template error", http.StatusInternalServerError)
	}
}

// requestMessageForExchange resolves an exchange's request bytes when the exchange's own
// Request pointer is nil (the restored-project case). It never guesses an id: the request
// index is the only authority, and when nothing resolves the pane says so — an honest
// empty pane beats fabricated bytes.
func requestMessageForExchange(st *core.TrafficStore, ex *core.Exchange) []byte {
	if st == nil || ex == nil {
		return nil
	}
	if ex.Request != nil {
		if msg, err := st.Get(*ex.Request); err == nil {
			return msg.Raw()
		}
		return nil
	}
	return nil
}

// ui2Detail is the model for one exchange's request/response pane.
type ui2Detail struct {
	ID          uint64
	Method      string
	Host        string
	Port        uint16
	Path        string
	Status      string
	Mime        string
	ResponseLen int
	DurationMs  uint64
	Request     string
	Response    string
	// Rendered panes + view state for the Pretty/Raw reading toggle. The strings stay:
	// the raw view renders exactly them, and tests read them straight.
	ReqPane    ui2PaneView
	RespPane   ui2PaneView
	ReqPretty  bool
	RespPretty bool
}

// ui2IssueGroup is one grouped issue (same issue name + host) for the issues tree.
type ui2IssueGroup struct {
	Name       string
	Severity   string
	Confidence string
	Host       string
	Count      int // occurrences
	FalsePos   bool
	IDs        []uint64
	FirstID    uint64
}

// ui2IssuesModel is the issues page fragment model.
type ui2IssuesModel struct {
	Groups   []ui2IssueGroup
	Total    int
	Severity map[string]int // lower-cased severity -> count
}

// handleUI2Issues serves GET /ui2/issues: the shell with the grouped issues list, or the
// groups fragment alone for an htmx swap.
func (s *Server) handleUI2Issues(w http.ResponseWriter, r *http.Request) {
	body := s.renderUI2Issues()
	if r.Header.Get("HX-Request") == "true" {
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		_, _ = w.Write([]byte(body))
		return
	}
	page := ui2Page{Title: "burpsy /ui2/ — Issues", View: "issues", Body: body}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	if err := ui2Templates.ExecuteTemplate(w, "layout.html", page); err != nil {
		http.Error(w, "template error", http.StatusInternalServerError)
	}
}

// renderUI2Issues groups findings by (issue name, host) — the same merge the store already
// does per target, rolled up one level for display — and renders the groups fragment.
// Evidence lives one click deep (the detail route), so the list payload stays flat.
func (s *Server) renderUI2Issues() template.HTML {
	findings := s.findings.All()
	// Same skip as handleIssues: no findings means no occurrence resolution, so the
	// whole-history snapshot would be built for an empty render.
	var idx exchangeIndex
	if len(findings) > 0 {
		idx = s.exchangeIndexFor(findings)
	}
	type key struct{ name, host string }
	order := make([]key, 0, len(findings))
	groups := map[key]*ui2IssueGroup{}
	sev := map[string]int{}
	for _, f := range findings {
		if s.isolatedAgainst(f, &idx) {
			continue
		}
		v := s.issueView(f, &idx, true)
		name := f.Name
		if v.IssueName != nil && *v.IssueName != "" {
			name = *v.IssueName
		}
		k := key{name: name, host: v.Host}
		g, ok := groups[k]
		if !ok {
			g = &ui2IssueGroup{Name: name, Severity: v.Severity, Confidence: v.Confidence, Host: v.Host, FirstID: v.ID}
			groups[k] = g
			order = append(order, k)
		}
		g.Count += len(v.Occurrences)
		if g.Count == 0 {
			g.Count = v.TimesSeen
		}
		g.FalsePos = g.FalsePos || v.FalsePositive
		g.IDs = append(g.IDs, v.ID)
		if !v.FalsePositive {
			sev[strings.ToLower(v.Severity)]++
		}
	}
	out := ui2IssuesModel{Groups: make([]ui2IssueGroup, 0, len(order)), Total: len(findings), Severity: sev}
	for _, k := range order {
		out.Groups = append(out.Groups, *groups[k])
	}
	var sb strings.Builder
	_ = ui2Templates.ExecuteTemplate(&sb, "issue_groups.html", out)
	return template.HTML(sb.String()) //nolint:gosec // html/template auto-escapes every field
}

// handleUI2IssueDetail serves GET /ui2/issues/{id}: one finding with its evidence excerpt,
// occurrences (exchange ids + paths) and the advisory detail — the pane the list omits.
func (s *Server) handleUI2IssueDetail(w http.ResponseWriter, r *http.Request) {
	id, err := strconv.ParseUint(r.PathValue("id"), 10, 64)
	if err != nil {
		http.Error(w, "Invalid issue ID", http.StatusBadRequest)
		return
	}
	f, err := s.findings.Get(id)
	if err != nil {
		http.Error(w, "Issue not found", http.StatusNotFound)
		return
	}
	idx := s.exchangeIndexFor([]*core.Finding{f})
	v := s.issueView(f, &idx, false)
	model := ui2IssueDetail{
		ID: v.ID, CheckName: v.CheckName, Severity: v.Severity, Confidence: v.Confidence,
		Host: v.Host, Param: v.Param, Evidence: v.Evidence, TimesSeen: v.TimesSeen,
		FalsePositive: v.FalsePositive, Comment: v.Comment, Source: v.Source,
		Detail: ptrString(v.Detail), Remediation: ptrString(v.Remediation),
	}
	for _, occ := range v.Occurrences {
		model.Occurrences = append(model.Occurrences, ui2Occurrence{ExchangeID: uint64(occ.ExchangeID), Path: occ.Path})
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	if err := ui2Templates.ExecuteTemplate(w, "issue_detail.html", model); err != nil {
		http.Error(w, "template error", http.StatusInternalServerError)
	}
}

// handleUI2AdvisoryDetail serves GET /ui2/advisories/{typeIndex}: one catalogue definition
// rendered as an HTML fragment for the detail pane. The JSON /api/advisories/{typeIndex} shape
// stays the API contract; this route is the console's rendering of it. Paragraphs come from
// advisory.PlainParagraphs (plain text, auto-escaped) — never the raw catalogue HTML.
func (s *Server) handleUI2AdvisoryDetail(w http.ResponseWriter, r *http.Request) {
	segment := r.PathValue("typeIndex")
	index, err := strconv.ParseUint(segment, 16, 32)
	if err != nil {
		http.Error(w, fmt.Sprintf("Type index %q is not a hexadecimal issue type index", segment),
			http.StatusNotFound)
		return
	}
	if s.advisories == nil {
		http.Error(w, "No issue-definition catalogue is loaded", http.StatusNotFound)
		return
	}
	def, ok := s.advisories.ByIndex(int(index))
	if !ok {
		http.Error(w, fmt.Sprintf("No issue definition with type index %s", segment), http.StatusNotFound)
		return
	}
	v := advisoryDetailView(def)
	model := ui2AdvisoryDetail{
		TypeIndex:   v.TypeIndex,
		Name:        v.Name,
		Severity:    v.TypicalSeverity,
		Description: v.DescriptionParagraphs,
		Remediation: v.RemediationParagraphs,
	}
	// Disclose index collisions: a tap on a shadowed row lands here, and the pane's
	// identity must name the shadow rather than let the row's name stand for this detail.
	for _, d := range s.advisories.ShadowedByIndex() {
		if d.TypeIndex == int(index) {
			model.Shadows = append(model.Shadows, d.Name)
		}
	}
	for _, ref := range v.References {
		model.References = append(model.References, ui2AdvisoryLink{Title: ref.Title, URL: ref.URL})
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	if err := ui2Templates.ExecuteTemplate(w, "advisory_detail.html", model); err != nil {
		http.Error(w, "template error", http.StatusInternalServerError)
	}
}

// ui2AdvisoryDetail is the model for one catalogue definition's detail pane.
type ui2AdvisoryDetail struct {
	TypeIndex   string
	Name        string
	Severity    string
	Description []string
	Remediation []string
	References  []ui2AdvisoryLink
	Shadows     []string
}

type ui2AdvisoryLink struct {
	Title string
	URL   string
}

// ui2IssueDetail is the model for one issue's detail pane.
type ui2IssueDetail struct {
	ID            uint64
	CheckName     string
	Severity      string
	Confidence    string
	Host          string
	Param         string
	Evidence      string
	TimesSeen     int
	FalsePositive bool
	Comment       string
	Source        string
	Detail        string
	Remediation   string
	Occurrences   []ui2Occurrence
}

type ui2Occurrence struct {
	ExchangeID uint64
	Path       string
}

func ptrString(p *string) string {
	if p == nil {
		return ""
	}
	return *p
}

// serveUI2Asset serves one vendored static file from the embedded ui2 tree. The name is
// allowlisted, not taken from the path: anything else 404s, so no request can make the
// handler read outside the embedded set.
func serveUI2Asset(w http.ResponseWriter, r *http.Request) {
	name := strings.TrimPrefix(r.URL.Path, "/ui2/")
	switch name {
	case "htmx.min.js", "sse.min.js", "app.js":
	default:
		http.Error(w, "not found", http.StatusNotFound)
		return
	}
	sub, err := fs.Sub(ui2FS, "ui2")
	if err != nil {
		http.Error(w, "ui2 unavailable", http.StatusInternalServerError)
		return
	}
	data, err := fs.ReadFile(sub, name)
	if err != nil {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}
	w.Header().Set("Content-Type", "text/javascript; charset=utf-8")
	w.Header().Set("Cache-Control", "no-cache")
	// #nosec G705 -- data is a vendored, embedded, allowlisted JS file, never request input.
	_, _ = w.Write(data)
}

package web

// ui2 site-map row actions (burpsy /ui2/ lane D1).
//
// The site map was the last read-only target view: the React tree's right-click menu can add a
// row to the target scope and seed Repeater from a row, while the /ui2/ table rendered the same
// rows with no way to act on them. This file closes exactly those two actions, no more:
//
//   - Add to scope: POST /ui2/sitemap/scope/confirm resolves the row's node from a FRESH
//     server-side tree (the form carries only the node's key, never host/port/path fields a
//     client could edit), mints a one-time confirmation for the exact /api/scope include call
//     and renders the review sheet; POST /ui2/sitemap/scope/run spends the token on the
//     reviewed call. The minted body is rebuilt from the sheet's hidden fields at run time, so
//     a tampered field fails the token digest and burns it - and a site map that drifts after
//     the review changes nothing: the rule the operator read is the rule that runs, which the
//     sheet says out loud. No traffic is sent by either step; the rule persists.
//   - Send to Repeater: GET /ui2/sitemap/repeater?key= loads the newest stored request under
//     the row into the Repeater editor as an editable draft. This sends nothing - the operator
//     still presses Send on the Repeater page, and the draft is the stored bytes as editable
//     text, never a byte-exact replay claim. Rows with no captured exchange, a request-less
//     tunnel, or bytes a textarea cannot carry unchanged get a named refusal instead of a
//     silently empty or corrupted editor.
//
// Both steps reuse the proven ui2 confirm gate (ui2MintConfirm / ui2DispatchConfirmed, the
// scope page's own flow) rather than inventing a second review mechanism.

import (
	"fmt"
	"html/template"
	"net/http"
	"strconv"
	"strings"

	"github.com/burpsy-go/burpsy/internal/core"
)

// ---- shared resolution helpers ---------------------------------------------------------------

// ui2SitemapSnapshot reads the live site map through the JSON handler's own view builder, the
// same way renderUI2Sitemap does, so a row action and the page it came from can never disagree
// about what the map holds.
func (s *Server) ui2SitemapSnapshot() (*sitemapTreeResp, string) {
	rec := newRecorder()
	s.sitemapGet(rec, newReq(http.MethodGet, "/api/sitemap"))
	var tree sitemapTreeResp
	if err := ui2DecodeJSON(rec.Body.Bytes(), &tree); err != nil {
		return nil, "site map unavailable: " + err.Error()
	}
	return &tree, ""
}

// ui2SitemapFindNode returns the tree node with exactly this key and the host it sits under.
// The key is the node's stated identity (nodeKey: scheme://host:port, plus NUL + path for a
// path node), so a lookup never re-parses it into a second host/path grammar that could drift
// from the first. The host is read off the tree instead: every top-level row is a host row
// whose Path IS the host (observed, inserted and unrequested builders all set it), so the host
// of any node is its top-level ancestor's Path - server state, not client-supplied fields, and
// not the node's HostName field, which is json:"-" and empty for observed rows.
func ui2SitemapFindNode(nodes []sitemapNodeView, key string) (*sitemapNodeView, string) {
	var found *sitemapNodeView
	host := ""
	var walk func(ns []sitemapNodeView, top string) bool
	walk = func(ns []sitemapNodeView, top string) bool {
		for i := range ns {
			t := top
			if t == "" {
				t = ns[i].Path
			}
			if ns[i].Key == key {
				found = &ns[i]
				host = t
				return true
			}
			if walk(ns[i].Children, t) {
				return true
			}
		}
		return false
	}
	walk(nodes, "")
	return found, host
}

// ui2SitemapNewestExchange names the newest captured exchange under a node: a path node's
// Recent holds its own latest exchanges, and a folder or host row's newest is the newest of
// anything beneath it. Each node's Recent keeps that path's last 20 exchanges, and a path's
// newest exchange is always inside its own last 20, so the subtree maximum is exact.
func ui2SitemapNewestExchange(n *sitemapNodeView) (core.ExchangeID, bool) {
	var best core.ExchangeID
	found := false
	var walk func(v *sitemapNodeView)
	walk = func(v *sitemapNodeView) {
		for _, id := range v.Recent {
			if !found || id > best {
				best = id
				found = true
			}
		}
		for i := range v.Children {
			walk(&v.Children[i])
		}
	}
	walk(n)
	return best, found
}

// ui2SitemapNodeLabel is how the review sheets and refusals name a row: the host for a host
// row, host + path for a path row.
func ui2SitemapNodeLabel(n *sitemapNodeView, host string) string {
	if strings.Contains(n.Key, "\x00") {
		return host + n.Path
	}
	return host
}

// ui2SitemapFields is the run step's form contract, mirroring the organizer's
// ui2WorkflowFields: every permitted field exactly once, nothing else, and no query fields -
// a run that answers to smuggled fields is how a reviewed call becomes a different call.
func ui2SitemapFields(r *http.Request, keys ...string) error {
	if err := r.ParseForm(); err != nil {
		return fmt.Errorf("invalid form")
	}
	if len(r.URL.Query()) != 0 {
		return fmt.Errorf("query fields are not permitted here")
	}
	allowed := map[string]bool{}
	for _, k := range keys {
		allowed[k] = true
		if len(r.PostForm[k]) != 1 {
			return fmt.Errorf("%s must be a single permitted field", k)
		}
	}
	for k, v := range r.PostForm {
		if !allowed[k] || len(v) != 1 {
			return fmt.Errorf("%s is not a single permitted field", k)
		}
	}
	return nil
}

// ---- Add to scope ----------------------------------------------------------------------------

// handleUI2SitemapScope routes POST /ui2/sitemap/scope/{action}: confirm renders the review
// step, run spends the reviewed call. The first click never changes the scope.
func (s *Server) handleUI2SitemapScope(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}
	switch r.PathValue("action") {
	case "run":
		s.ui2SitemapScopeRun(w, r)
	case "confirm":
		s.ui2SitemapScopeConfirm(w, r)
	default:
		s.ui2SitemapScopeSheet(w, map[string]any{"error": "unknown site-map scope action"})
	}
}

// ui2SitemapScopeSheet renders the review fragment (which is also how a refusal is shown).
func (s *Server) ui2SitemapScopeSheet(w http.ResponseWriter, model map[string]any) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	_, _ = w.Write([]byte(ui2Exec("sitemap_action_confirm.html", model)))
}

// ui2SitemapScopeConfirm resolves the row's node from server state and mints the confirmation
// for the exact include call. The form carries the row key in the post URL's query (a NUL-
// carrying key cannot cross a form field unchanged, and only the key crosses at all): every
// identity fact in the minted call - host, port, scheme, path prefix - is read off the node
// the key names NOW, never off client-supplied fields. A row that vanished since the page
// loaded is a named refusal, not a rule aimed at a re-parsed guess.
func (s *Server) ui2SitemapScopeConfirm(w http.ResponseWriter, r *http.Request) {
	fail := func(msg string) { s.ui2SitemapScopeSheet(w, map[string]any{"error": msg}) }
	if err := r.ParseForm(); err != nil || len(r.PostForm) != 0 {
		fail("a site-map row action carries no form fields - use the row's own button")
		return
	}
	q := r.URL.Query()
	if len(q) != 1 || len(q["key"]) != 1 {
		fail("exactly one site-map row key is required")
		return
	}
	tree, errText := s.ui2SitemapSnapshot()
	if errText != "" {
		fail(errText)
		return
	}
	node, host := ui2SitemapFindNode(tree.Tree, q.Get("key"))
	if node == nil {
		fail("that site-map row is gone - the map changed since the page loaded; reload the site map and choose again")
		return
	}
	if host == "" || node.Port == 0 {
		fail("the row's host and port could not be resolved from the live map - reload the site map and choose again")
		return
	}
	protocol := "http"
	if node.TLS {
		protocol = "https"
	}
	payload := map[string]any{
		"action":   "include",
		"pattern":  host,
		"port":     node.Port,
		"protocol": protocol,
	}
	pathPrefix := ""
	if strings.Contains(node.Key, "\x00") {
		// A path row scopes its subtree: the rule's path arm is a literal prefix
		// (core.ScopeRule.PathPrefix), which is what "this branch of the map" means.
		payload["path"] = node.Path
		pathPrefix = node.Path
	}
	body, _ := ui2Marshal(payload)
	token, preview, mintErr := s.ui2MintConfirm("/api/scope", http.MethodPost, "/api/scope", body)
	s.ui2SitemapScopeSheet(w, map[string]any{
		"node":     ui2SitemapNodeLabel(node, host),
		"pattern":  host,
		"port":     strconv.Itoa(int(node.Port)),
		"protocol": protocol,
		"path":     pathPrefix,
		"inscope":  node.InScope,
		"preview":  preview,
		"token":    token,
		"error":    mintErr,
	})
}

// ui2SitemapScopeRun spends the confirmation on the exact reviewed call and re-renders the
// rows with the outcome. The body is rebuilt from the sheet's hidden fields and validated
// field by field; the token digest refuses anything that no longer matches what was minted,
// and the API's own refusals (a duplicate tuple, an unreadable arm) render as the note.
func (s *Server) ui2SitemapScopeRun(w http.ResponseWriter, r *http.Request) {
	note := ""
	done := ""
	payload, errText := ui2SitemapScopePayload(r)
	if errText != "" {
		note = errText
	} else {
		_, dispatchErr := s.ui2DispatchConfirmed(http.MethodPost, "/api/scope", payload, r.PostFormValue("token"))
		if dispatchErr != "" {
			note = dispatchErr
		} else {
			done = ui2SitemapScopeDoneNote(payload)
		}
	}
	s.ui2SitemapRows(w, note, done)
}

// ui2SitemapScopePayload rebuilds the reviewed include call from the sheet's hidden fields.
func ui2SitemapScopePayload(r *http.Request) (map[string]any, string) {
	if err := ui2SitemapFields(r, "token", "pattern", "port", "protocol", "path"); err != nil {
		return nil, err.Error()
	}
	pattern := strings.TrimSpace(r.PostFormValue("pattern"))
	if pattern == "" {
		return nil, "the reviewed rule has no host pattern - review again"
	}
	payload := map[string]any{"action": "include", "pattern": pattern}
	if p := strings.TrimSpace(r.PostFormValue("port")); p != "" {
		n, err := strconv.Atoi(p)
		if err != nil || n < 1 || n > 65535 {
			return nil, "port must be 1-65535"
		}
		payload["port"] = n
	}
	if p := strings.TrimSpace(r.PostFormValue("protocol")); p != "" {
		if p != "http" && p != "https" {
			return nil, "protocol must be http or https"
		}
		payload["protocol"] = p
	}
	if p := r.PostFormValue("path"); p != "" {
		payload["path"] = p
	}
	return payload, ""
}

// ui2SitemapScopeDoneNote states the landed rule in the run's own words, because the API's
// success view is the whole scope, not the one rule this review was about.
func ui2SitemapScopeDoneNote(payload map[string]any) string {
	rule := fmt.Sprintf("host %s, port %v, %s only", payload["pattern"], payload["port"], payload["protocol"])
	if p, ok := payload["path"].(string); ok && p != "" {
		rule += ", path prefix " + p
	}
	return "Scope rule added: " + rule + ". No traffic was sent; the proxy and tools may now reach it."
}

// ui2SitemapRows re-renders the table fragment with the outcome line. The note is a refusal
// the operator must read; the done line is the landed fact.
func (s *Server) ui2SitemapRows(w http.ResponseWriter, note, done string) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	tree, errText := s.ui2SitemapSnapshot()
	if errText != "" {
		_, _ = w.Write([]byte(ui2Exec("error.html", ui2Error{Message: errText})))
		return
	}
	flat := flattenSitemap(tree.Tree, 0, nil)
	_, _ = w.Write([]byte(ui2Exec("sitemap.html", ui2SitemapModel{Tree: *tree, Flat: flat, Note: note, Done: done})))
}

// ---- Send to Repeater ------------------------------------------------------------------------

// handleUI2SitemapRepeater serves GET /ui2/sitemap/repeater?key=: the Repeater editor with the
// newest stored request under the row loaded as the draft. Loading a draft sends nothing; the
// send stays on the Repeater page's own reviewed path (/ui2/repeater/send), which is unchanged.
// Every failure is named - a gone row, an empty branch, a request-less tunnel, or bytes a text
// editor cannot carry unchanged - because an editor that opens empty or corrupted reads as
// "nothing was captured", the lie this surface exists to avoid.
func (s *Server) handleUI2SitemapRepeater(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}
	fail := func(msg string) {
		ui2RenderPage(w, "burpsy /ui2/ — Site map", "sitemap", ui2Exec("error.html", ui2Error{Message: msg}))
	}
	q := r.URL.Query()
	if len(q) != 1 || len(q["key"]) != 1 {
		fail("exactly one site-map row key is required")
		return
	}
	tree, errText := s.ui2SitemapSnapshot()
	if errText != "" {
		fail(errText)
		return
	}
	node, host := ui2SitemapFindNode(tree.Tree, q.Get("key"))
	if node == nil {
		fail("that site-map row is gone - reload the site map and choose again")
		return
	}
	id, ok := ui2SitemapNewestExchange(node)
	if !ok {
		fail("nothing has been captured under " + ui2SitemapNodeLabel(node, host) + " yet - there is no stored request to load into Repeater")
		return
	}
	var ex *core.Exchange
	for _, e := range s.store.Exchanges() {
		if e.ID == id {
			ex = e
			break
		}
	}
	if ex == nil {
		fail(fmt.Sprintf("exchange #%d is no longer in the store - reload the site map", uint64(id)))
		return
	}
	if ex.Request == nil {
		fail(fmt.Sprintf("exchange #%d has no stored request - a blind tunnel cannot seed Repeater", uint64(id)))
		return
	}
	msg, err := s.store.Get(*ex.Request)
	if err != nil {
		fail(fmt.Sprintf("the stored request for exchange #%d is unavailable: %v", uint64(id), err))
		return
	}
	raw := msg.Raw()
	if !ui2TextareaSafe(raw) {
		fail(fmt.Sprintf("the stored request for exchange #%d carries bytes a text editor cannot keep unchanged (invalid UTF-8 or NUL) - use the console's binary-safe view instead; nothing was loaded", uint64(id)))
		return
	}
	// The notice is composition, not a template change: the Repeater fragment stays byte-
	// identical and the page states what loading a stored draft means where the operator reads it.
	notice := fmt.Sprintf("Draft loaded from stored exchange #%d under %s. This is an editable text copy of the stored request - sending happens from the editor and is not a byte-exact replay of the capture.",
		uint64(id), ui2SitemapNodeLabel(node, host))
	body := templateHTML(`<p class="meta">`+template.HTMLEscapeString(notice)+`</p>`) +
		ui2Exec("repeater.html", map[string]any{"draft": string(raw), "result": nil})
	ui2RenderPage(w, "burpsy /ui2/ — Repeater", "repeater", body)
}
